await story('P2-A8-09-mismatch-Stop-phone',async()=>{
 const n=await context(cases[1]);await signIn(n.p,'negative');await n.p.fill('#quickFleetLabel','Pass2 mismatch control');await n.p.locator('[data-quick-pairing] form button[type=submit]').click();await n.p.locator('[data-quick-pairing] .hub-fp-groups').waitFor();const code=(await n.p.locator('[data-quick-pairing] .hub-fp-groups').first().innerText()).trim();const h=join(scratch,'mismatch-member');mkdirSync(h,{mode:0o700});const ep=createHubMemberPairingApi({home:h,enabled:()=>true});extraPairings.push(ep);fx.fm.attachHubMemberPairing(ep);const l=await hostPage(cases[0]);await l.p.fill('#hubAddress',memberOrigin);await l.p.fill('#hubCode',code);await l.p.locator('#hub-connect form button[type=submit]').click();await l.p.locator('.hub-local-confirm').waitFor();await n.p.getByRole('button',{name:'指紋不同',exact:true}).waitFor();check('pending still current on phone',await n.p.locator('[data-quick-pairing] .hub-steps>li').first().getAttribute('class')==='now');await n.p.getByRole('button',{name:'指紋不同',exact:true}).scrollIntoViewIfNeeded();await shot(n.p,'P2-A8-09-phone-pending');await n.p.getByRole('button',{name:'指紋不同',exact:true}).click();await n.p.getByText('已停止配對',{exact:true}).waitFor();check('mismatch no credential',ep.view().state!=='paired');await shot(n.p,'P2-A8-09-phone-mismatch-stopped');ep.cancel();await n.ctx.close();await l.ctx.close();activateMount(globalThis.p2Primary);
});
await story('P2-A8-10-exact-revoke-retains-control',async()=>{
 await ownerOther.p.locator('[data-pairing-notice] .btn-danger').first().click();await ownerOther.p.locator('[data-pairing-notice] .tag').first().waitFor();await shot(ownerOther.p,'P2-A8-10-exact-owner-revoke');await waitFor(()=>globalThis.p2Control.online,'independent control reconnects after version refresh',20000);check('independent manual credential remains paired and Online',globalThis.p2Control.api.view().state==='paired');
 const m=await context(cases[0]);await signIn(m.p,'manual');await m.p.locator('[data-fleet-status=active]').waitFor();check('control fleet active in own welcome',true);await shot(m.p,'P2-A8-10-control-active');await m.ctx.close();
});
